#!/usr/bin/env node
// Differential test harness: compares a Node port of test11.py against the
// reference executable /workspace/dataset/test11_executable.
//
// Usage:  node /tmp/difftest.mjs /output/test11.mjs
//
// Zero external dependencies. ESM only. This file is deliberately ASCII-only:
// all exotic test strings are built with \u escapes / String.fromCodePoint.

import { spawnSync } from 'node:child_process';
import { basename, resolve } from 'node:path';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const REFERENCE = '/workspace/dataset/test11_executable';
const REF_PROG = 'test11_executable';

// ---------------------------------------------------------------------------
// helpers for building exotic argv strings without non-ASCII source bytes
// ---------------------------------------------------------------------------

/** String.fromCodePoint shorthand. */
const cp = (...codes) => String.fromCodePoint(...codes);

const NBSP  = cp(0x00a0);   // White_Space, non-printable (Zs)
const NEL   = cp(0x0085);   // White_Space, non-printable (Cc)
const OGHAM = cp(0x1680);   // White_Space (Zs)
const LSEP  = cp(0x2028);   // White_Space (Zl)
const PSEP  = cp(0x2029);   // White_Space (Zp)
const NNBSP = cp(0x202f);   // White_Space (Zs)
const MMSP  = cp(0x205f);   // White_Space (Zs)
const IDSP  = cp(0x3000);   // White_Space (Zs)
const ENQD  = cp(0x2000);   // White_Space (Zs)
const HAIR  = cp(0x200a);   // White_Space (Zs)
const VT    = cp(0x000b);   // White_Space, repr -> \x0b
const FF    = cp(0x000c);   // White_Space, repr -> \x0c
const ZWSP  = cp(0x200b);   // NOT White_Space (Cf) -> invalid int
const BOM   = cp(0xfeff);   // NOT White_Space (Cf) -> invalid int
const FS    = cp(0x001c);   // NOT White_Space (Cc) -> invalid int

const ARABIC_5     = cp(0x0665);   // Nd -> 5
const ARABIC_6     = cp(0x0666);   // Nd -> 6
const ARABIC_1     = cp(0x0661);   // Nd -> 1
const ARABIC_2     = cp(0x0662);   // Nd -> 2
const FULLWIDTH_1  = cp(0xff11);   // Nd -> 1
const FULLWIDTH_2  = cp(0xff12);   // Nd -> 2
const EXT_ARABIC_5 = cp(0x06f5);   // Nd -> 5
const ASTRAL_5     = cp(0x1d7dd);  // Nd (astral) -> 5
const SUPER_2      = cp(0x00b2);   // No, not a decimal digit -> invalid
const ROMAN_5      = cp(0x2164);   // Nl, not a decimal digit -> invalid

const PUA       = cp(0xe000);            // Co -> repr \ue000
const NONCHAR   = cp(0xfffe);            // Cn -> repr \ufffe
const CTRL1     = cp(0x0001);            // Cc -> repr \x01
const EACUTE_PM = cp(0x00e9, 0x00b1);    // printable, passes through literally
const DESERET = cp(0x10400);         // astral printable

// ---------------------------------------------------------------------------
// CASES
// ---------------------------------------------------------------------------

const CASES = [
  // --- 1. plain happy paths ------------------------------------------------
  { group: 'normal', argv: ['--a', '2', '--b', '3'] },
  { group: 'normal', argv: ['--a', '0', '--b', '0'] },
  { group: 'normal', argv: ['--a', '1', '--b', '0'] },
  { group: 'normal', argv: ['--a', '0', '--b', '1'] },
  { group: 'normal', argv: ['--a', '1', '--b', '1'] },
  { group: 'normal', argv: ['--a', '10', '--b', '7'] },
  { group: 'normal', argv: ['--a', '7', '--b', '10'] },
  { group: 'normal', argv: ['--a', '50', '--b', '25'] },
  { group: 'normal', argv: ['--a', '25', '--b', '50'] },
  { group: 'normal', argv: ['--a', '100', '--b', '100'] },
  { group: 'normal', argv: ['--a', '200', '--b', '0'] },
  { group: 'normal', argv: ['--a', '0', '--b', '200'] },
  { group: 'normal', argv: ['--b', '3', '--a', '2'] },
  { group: 'normal', argv: ['--b', '0', '--a', '0'] },

  // --- 2. negatives and cancelling sums ------------------------------------
  { group: 'negative', argv: ['--a', '-3', '--b', '2'] },
  { group: 'negative', argv: ['--a', '2', '--b', '-3'] },
  { group: 'negative', argv: ['--a', '-5', '--b', '5'] },
  { group: 'negative', argv: ['--a', '5', '--b', '-5'] },
  { group: 'negative', argv: ['--a', '-1', '--b', '-1'] },
  { group: 'negative', argv: ['--a', '-200', '--b', '200'] },
  { group: 'negative', argv: ['--a', '200', '--b', '-200'] },
  { group: 'negative', argv: ['--a', '-1', '--b', '0'] },
  { group: 'negative', argv: ['--a', '0', '--b', '-1'] },
  { group: 'negative', argv: ['--a', '-7', '--b', '10'] },
  { group: 'negative', argv: ['--a', '10', '--b', '-7'] },
  { group: 'negative', argv: ['--a', '-0', '--b', '5'] },

  // --- 3. "=" form ---------------------------------------------------------
  { group: 'equals', argv: ['--a=2', '--b=3'] },
  { group: 'equals', argv: ['--a=0', '--b=0'] },
  { group: 'equals', argv: ['--a=-3', '--b=2'] },
  { group: 'equals', argv: ['--a=2', '--b', '3'] },
  { group: 'equals', argv: ['--a', '2', '--b=3'] },
  { group: 'equals', argv: ['--a=+5', '--b=007'] },
  { group: 'equals', argv: ['--a=', '--b=1'] },

  { group: 'equals', argv: ['--a=', '--b=1'] },
  { group: 'equals', argv: ['--b=3', '--a=2'] },

  // --- 4. repeats overwrite ------------------------------------------------
  { group: 'repeat', argv: ['--a', '1', '--a', '2', '--b', '3'] },
  { group: 'repeat', argv: ['--b', '1', '--b', '2', '--a', '3'] },
  { group: 'repeat', argv: ['--a', '1', '--b', '2', '--a', '-1'] },
  { group: 'repeat', argv: ['--a=1', '--a=2', '--b=0'] },
  { group: 'repeat', argv: ['--a', '5', '--b', '5', '--a', '0', '--b', '0'] },

  // --- 5. help flags -------------------------------------------------------
  { group: 'help', argv: ['-h'] },
  { group: 'help', argv: ['--help'] },
  { group: 'help', argv: ['--h'] },
  { group: 'help', argv: ['--he'] },
  { group: 'help', argv: ['--hel'] },
  { group: 'help', argv: ['--a', '3', '--b', '2', '-h'] },
  { group: 'help', argv: ['-h', '--a', '3'] },
  { group: 'help', argv: ['--help', '--c', '3'] },
  { group: 'help', argv: ['-h', 'bogus'] },
  { group: 'help', argv: ['--a', '1', '--b', '2', '--c', '3', '-h'] },
  { group: 'help', argv: ['--c', '3', '-h'] },
  { group: 'help', argv: ['--a', 'x', '--b', '1', '-h'] },

  // --- 6. missing required -------------------------------------------------
  { group: 'required', argv: [] },
  { group: 'required', argv: ['--a', '1'] },
  { group: 'required', argv: ['--b', '1'] },
  { group: 'required', argv: ['--a=1'] },
  { group: 'required', argv: ['--b=1'] },
  { group: 'required', argv: ['--a', '1', '--a', '2'] },
  { group: 'required', argv: ['--a', '-4'] },

  // --- 7. invalid int values ----------------------------------------------
  { group: 'invalid-int', argv: ['--a', 'x', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '1', '--b', 'x'] },
  { group: 'invalid-int', argv: ['--a', '1.5', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '0x10', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '0b101', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '1e3', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '_10', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '10_', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '1__0', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '+_5', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '- 5', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '5 5', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', ' ', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '+', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '-', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '5.0', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '99999999999999999999999999x', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', SUPER_2, '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', ROMAN_5, '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', ZWSP + '5', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '5' + BOM, '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', FS + '5', '--b', '1'] },
  { group: 'invalid-int', argv: ['--a', '5' + FS, '--b', '1'] },

  // --- 8. valid exotic ints -----------------------------------------------
  { group: 'exotic-int', argv: ['--a', '1_0', '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', ' 5 ', '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', '+5', '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', '007', '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', '000', '--b', '0'] },
  { group: 'exotic-int', argv: ['--a', '-0', '--b', '+0'] },
  { group: 'exotic-int', argv: ['--a', '-1_0', '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', ARABIC_5, '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', ARABIC_1 + ARABIC_2, '--b', '0'] },
  { group: 'exotic-int', argv: ['--a', FULLWIDTH_1 + FULLWIDTH_2, '--b', '0'] },
  { group: 'exotic-int', argv: ['--a', ARABIC_5 + '_' + ARABIC_6, '--b', '0'] },
  { group: 'exotic-int', argv: ['--a', ARABIC_5 + '5', '--b', '0'] },
  { group: 'exotic-int', argv: ['--a', EXT_ARABIC_5, '--b', '0'] },
  { group: 'exotic-int', argv: ['--a', ASTRAL_5, '--b', '0'] },
  { group: 'exotic-int', argv: ['--a', '9' + ASTRAL_5, '--b', '0'] },
  { group: 'exotic-int', argv: ['--a', '-' + ASTRAL_5, '--b', '5'] },
  { group: 'exotic-int', argv: ['--a', NBSP + '5' + NBSP, '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', LSEP + '5' + PSEP, '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', VT + '5' + FF, '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', IDSP + '5' + IDSP, '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', NEL + '5', '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', OGHAM + '5', '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', MMSP + '5' + NNBSP, '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', '\t5\n', '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', '\r\n 5 \r\n', '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', ENQD + '5' + HAIR, '--b', '1'] },
  { group: 'exotic-int', argv: ['--a', ENQD + NBSP + IDSP + '1_2' + NEL, '--b', '0'] },

  // --- 9. repr()-exercising invalid values ---------------------------------
  { group: 'repr', argv: ['--a', "it's", '--b', '1'] },
  { group: 'repr', argv: ['--a', 'both\'and"', '--b', '1'] },
  { group: 'repr', argv: ['--a', 'he said "hi"', '--b', '1'] },
  { group: 'repr', argv: ['--a', "'", '--b', '1'] },
  { group: 'repr', argv: ['--a', '"', '--b', '1'] },
  { group: 'repr', argv: ['--a', '\\back', '--b', '1'] },
  { group: 'repr', argv: ['--a', '\\\\', '--b', '1'] },
  { group: 'repr', argv: ['--a', "\\'", '--b', '1'] },
  { group: 'repr', argv: ['--a', 'a\nb', '--b', '1'] },
  { group: 'repr', argv: ['--a', 'a\tb', '--b', '1'] },
  { group: 'repr', argv: ['--a', 'a\rb', '--b', '1'] },
  { group: 'repr', argv: ['--a', 'a' + VT + 'b', '--b', '1'] },
  { group: 'repr', argv: ['--a', 'a' + FF + 'b', '--b', '1'] },
  { group: 'repr', argv: ['--a', VT, '--b', '1'] },
  { group: 'repr', argv: ['--a', FF, '--b', '1'] },
  { group: 'repr', argv: ['--a', CTRL1, '--b', '1'] },
  { group: 'repr', argv: ['--a', NBSP, '--b', '1'] },
  { group: 'repr', argv: ['--a', LSEP, '--b', '1'] },
  { group: 'repr', argv: ['--a', BOM, '--b', '1'] },
  { group: 'repr', argv: ['--a', PUA, '--b', '1'] },
  { group: 'repr', argv: ['--a', NONCHAR, '--b', '1'] },
  { group: 'repr', argv: ['--a', FS, '--b', '1'] },
  { group: 'repr', argv: ['--a', EACUTE_PM, '--b', '1'] },
  { group: 'repr', argv: ['--a', DESERET, '--b', '1'] },
  { group: 'repr', argv: ['--a', 'x' + DESERET + PUA + "'" + '"', '--b', '1'] },
  { group: 'repr', argv: ['--a', "mix'" + CTRL1 + '\\', '--b', '1'] },

  // --- 10. unrecognized arguments -----------------------------------------
  { group: 'unrecognized', argv: ['--a', '1', '--b', '2', '--c', '3'] },
  { group: 'unrecognized', argv: ['--a', '1', '--b', '2', 'extra'] },
  { group: 'unrecognized', argv: ['--a', '1', '--b', '2', '--'] },
  { group: 'unrecognized', argv: ['--a', '1', '--b', '2', 'e1', 'e2'] },
  { group: 'unrecognized', argv: ['--a', '1', '--b', '2', '-x'] },
  { group: 'unrecognized', argv: ['--a', '1', '--b', '2', '--c'] },
  { group: 'unrecognized', argv: ['--a', '1', '--b', '2', '--c=3'] },
  { group: 'unrecognized', argv: ['extra', '--a', '1', '--b', '2'] },
  { group: 'unrecognized', argv: ['--a', '1', '--b', '2', '-'] },
  { group: 'unrecognized', argv: ['--a', '1', '--b', '2', '--', 'z'] },
  { group: 'unrecognized', argv: ['-a', '1', '--b', '1'] },
  { group: 'unrecognized', argv: ['--a', '1', '-b', '1'] },

  // --- 11. expected one argument ------------------------------------------
  { group: 'expected-one', argv: ['--a', '--b', '1'] },
  { group: 'expected-one', argv: ['--a', '1', '--b'] },
  { group: 'expected-one', argv: ['--a'] },
  { group: 'expected-one', argv: ['--b'] },
  { group: 'expected-one', argv: ['--a', '--b'] },
  { group: 'expected-one', argv: ['--a', '--5', '--b', '1'] },
  { group: 'expected-one', argv: ['--a', '1', '--b', '--5'] },
  { group: 'expected-one', argv: ['--a', '1', '--b', '2', '--a'] },
  { group: 'expected-one', argv: ['--a', '-h', '--b', '1'] },

  // --- 12. competing error kinds ------------------------------------------
  { group: 'competing', argv: ['--a', 'x', '--c', '3'] },
  { group: 'competing', argv: ['--c', '3'] },
  { group: 'competing', argv: ['--a', '1', '--c', '3'] },
  { group: 'competing', argv: ['-a', '1', '-b', '2'] },
  { group: 'competing', argv: ['--a', 'x', '--b', 'y'] },
  { group: 'competing', argv: ['--a', 'x', '--b', '1', 'extra'] },
  { group: 'competing', argv: ['--b', '1', '--a'] },
  { group: 'competing', argv: ['bogus'] },
];

// ---------------------------------------------------------------------------
// formatting helpers
// ---------------------------------------------------------------------------

/** JSON.stringify but escape every non-ASCII codepoint so output stays ASCII. */
function asciiJson(value) {
  const raw = JSON.stringify(value);
  let out = '';
  for (const ch of raw) {
    const c = ch.codePointAt(0);
    if (c < 0x80) {
      out += ch;
    } else if (c < 0x10000) {
      out += '\\u' + c.toString(16).padStart(4, '0');
    } else {
      // emit as surrogate pair escapes so it round-trips through JSON.parse
      for (let i = 0; i < ch.length; i++) {
        out += '\\u' + ch.charCodeAt(i).toString(16).padStart(4, '0');
      }
    }
  }
  return out;
}

function diffBlock(label, expected, actual) {
  if (expected === actual) return null;
  const e = String(expected).split('\n');
  const a = String(actual).split('\n');
  const n = Math.max(e.length, a.length);
  const out = [`    --- ${label} (- reference / + port) ---`];
  for (let i = 0; i < n; i++) {
    const ev = e[i];
    const av = a[i];
    if (ev === av) {
      out.push(`      ${String(i + 1).padStart(2)}   ${asciiJson(ev)}`);
    } else {
      if (ev !== undefined) out.push(`      ${String(i + 1).padStart(2)} - ${asciiJson(ev)}`);
      if (av !== undefined) out.push(`      ${String(i + 1).padStart(2)} + ${asciiJson(av)}`);
    }
  }
  return out.join('\n');
}

// ---------------------------------------------------------------------------
// runner
// ---------------------------------------------------------------------------

function run(cmd, args) {
  const r = spawnSync(cmd, args, {
    shell: false,
    encoding: 'utf8',
    timeout: 10000,
    maxBuffer: 32 * 1024 * 1024,
  });
  if (r.error) {
    return { stdout: '', stderr: '', status: null, failure: String(r.error && r.error.message) };
  }
  return {
    stdout: r.stdout === null || r.stdout === undefined ? '' : r.stdout,
    stderr: r.stderr === null || r.stderr === undefined ? '' : r.stderr,
    status: r.status,
    signal: r.signal || null,
    failure: null,
  };
}

function replaceAll(haystack, needle, replacement) {
  return haystack.split(needle).join(replacement);
}

function main() {
  const rawEntry = process.argv[2];
  if (!rawEntry) {
    process.stderr.write('usage: node difftest.mjs <path-to-entry.mjs>\n');
    process.exit(2);
  }
  const entry = resolve(rawEntry);
  if (!existsSync(entry)) {
    process.stderr.write(`difftest: entry file not found: ${entry}\n`);
    process.exit(2);
  }
  if (!existsSync(REFERENCE)) {
    process.stderr.write(`difftest: reference not found: ${REFERENCE}\n`);
    process.exit(2);
  }
  const portProg = basename(entry);

  let passed = 0;
  const failures = [];
  let dots = 0;

  for (let i = 0; i < CASES.length; i++) {
    const c = CASES[i];
    const ref = run(REFERENCE, c.argv);
    const port = run(process.execPath, [entry, ...c.argv]);

    // Normalize ONLY the prog name in the reference output.
    const expStdout = replaceAll(ref.stdout, REF_PROG, portProg);
    const expStderr = replaceAll(ref.stderr, REF_PROG, portProg);
    const expStatus = ref.status;

    const problems = [];
    if (ref.failure) problems.push(`    reference spawn failure: ${ref.failure}`);
    if (port.failure) problems.push(`    port spawn failure: ${port.failure}`);
    const dOut = diffBlock('stdout', expStdout, port.stdout);
    const dErr = diffBlock('stderr', expStderr, port.stderr);
    if (dOut) problems.push(dOut);
    if (dErr) problems.push(dErr);
    if (expStatus !== port.status) {
      problems.push(`    --- status --- reference=${expStatus} port=${port.status}` +
        (port.signal ? ` (port signal ${port.signal})` : '') +
        (ref.signal ? ` (reference signal ${ref.signal})` : ''));
    }

    if (problems.length === 0) {
      passed++;
      process.stdout.write('.');
      dots++;
      if (dots % 60 === 0) process.stdout.write('\n');
    } else {
      process.stdout.write('F');
      dots++;
      if (dots % 60 === 0) process.stdout.write('\n');
      failures.push(
        `\nFAIL #${i + 1} [${c.group}] argv=${asciiJson(c.argv)}\n` + problems.join('\n')
      );
    }
  }

  if (dots % 60 !== 0) process.stdout.write('\n');
  for (const f of failures) process.stdout.write(f + '\n');

  process.stdout.write(`RESULT: ${passed}/${CASES.length} passed\n`);
  process.exit(passed === CASES.length ? 0 : 1);
}

export { CASES, asciiJson };

// Only run when invoked directly (importable for tooling, e.g. the case-list doc).
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main();
}
